import { RequestConfig } from 'umi';

export interface RawResponseType<T extends any = any> {
  /** 状态码，0为正常返回 */
  errno: number;
  /** 错误信息 */
  error?: string;
  /** 返回数据 */
  data: T;
  message?: string;
}

export const request: RequestConfig = {
  headers: {
    'X-Requested-With': 'XMLHttpRequest',
  },
};
export default request;
