// 运行时配置
import './common.less';

export type InitialState = {
  pluginConfig: Window['pluginConfig'];
  projectConfig: Window['projectConfig'];
};

if (!window.pluginConfig) {
  window.pluginConfig = {
    theme: 'dark',
    ide: 'jetbrains',
  };
}
if (!window.projectConfig) {
  window.projectConfig = {};
}

export async function getInitialState(): Promise<InitialState> {
  const { pluginConfig, projectConfig } = window;
  const initialData: InitialState = {
    pluginConfig,
    projectConfig,
  } as InitialState;
  return initialData;
}

export { request } from '@/services/Api/requestConfig';
