/* eslint-disable no-case-declarations */
import { useCallback, useReducer } from 'react';

type MessageHandler = (payload: any) => void;
type MessageRegisterState = Record<
  string,
  Array<{ handler: MessageHandler; id: symbol }>
>;

interface RegisterAction {
  type: 'register';
  payload: {
    command: string;
    handler: MessageHandler;
    id: symbol;
  };
}
interface UnregisterAction {
  type: 'unregister';
  payload: {
    command: string;
    id: symbol;
  };
}

/**
 * 注册处理消息的方法，JsBridge收到消息后会通过对应的命令获取到对应的方法，然后执行
 */
export default function useMessageRegister() {
  const [handlers, dispatch] = useReducer(
    (
      state: MessageRegisterState,
      action: RegisterAction | UnregisterAction,
    ) => {
      const {
        type,
        payload: { command },
      } = action;
      switch (type) {
        case 'register': {
          const { handler, id } = action.payload;
          const targetCommand = state[command] || [];
          return {
            ...state,
            [command]: [...targetCommand, { handler, id }],
          };
        }
        case 'unregister': {
          const { [command]: targetCommand = [], ...rest } = state;
          const { id } = action.payload;
          return {
            ...rest,
            [command]: targetCommand.filter((item) => item.id !== id),
          };
        }
        default:
          return state;
      }
    },
    {},
  );

  const register = useCallback(
    <T extends any = any>(command: string, handler: (payload: T) => void) => {
      const handlerId = Symbol(command);
      dispatch({
        type: 'register',
        payload: {
          command,
          handler,
          id: handlerId,
        },
      });
      return handlerId;
    },
    [dispatch],
  );
  const unregister = useCallback(
    (command: string, id: symbol) => {
      dispatch({
        type: 'unregister',
        payload: {
          command,
          id,
        },
      });
    },
    [dispatch],
  );

  return {
    handlers,
    register,
    unregister,
  };
}
